--
-- Name: immutable_unaccent(text); Type: FUNCTION; Schema: matching; Owner: -
--

CREATE FUNCTION matching.immutable_unaccent(text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$ SELECT public.unaccent('public.unaccent', $1) $_$;


