--
-- Name: tt17_assessments; Type: TABLE; Schema: assessment; Owner: -
--

CREATE TABLE assessment.tt17_assessments (
    id uuid NOT NULL,
    enterprise_id uuid NOT NULL,
    enterprise_name character varying(255) DEFAULT ''::character varying NOT NULL,
    tax_code character varying(30) DEFAULT ''::character varying NOT NULL,
    assessment_year integer NOT NULL,
    scope_type character varying(30) DEFAULT 'PROVINCE'::character varying NOT NULL,
    scope_id character varying(20) DEFAULT 'HN'::character varying NOT NULL,
    industry_code character varying(20) DEFAULT 'C.10'::character varying NOT NULL,
    status character varying(30) DEFAULT 'DRAFT'::character varying NOT NULL,
    survey_data_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    scores_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    audit_trail_json jsonb,
    review_notes character varying(2000),
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewer_id uuid,
    submitted_at_utc timestamp with time zone,
    approved_at_utc timestamp with time zone,
    legacy_source_system character varying(50),
    legacy_source_table character varying(80),
    legacy_id character varying(100),
    legacy_source_hash character varying(64),
    legacy_migrated_at timestamp with time zone,
    legacy_mapping_version character varying(30),
    legacy_batch_id uuid
);


--
-- Name: audit_events; Type: TABLE; Schema: audit; Owner: -
--

CREATE TABLE audit.audit_events (
    id uuid NOT NULL,
    actor_ref uuid,
    actor_role character varying(20) NOT NULL,
    action character varying(100) NOT NULL,
    object_kind character varying(60) NOT NULL,
    object_id uuid,
    object_version integer,
    purpose character varying(60),
    outcome character varying(20) NOT NULL,
    rule_id character varying(120),
    correlation_id character varying(100) NOT NULL,
    ip_address character varying(64),
    user_agent character varying(512),
    details character varying(4000),
    occurred_at timestamp with time zone NOT NULL
);


--
-- Name: anchor_policies; Type: TABLE; Schema: blockchain; Owner: -
--

CREATE TABLE blockchain.anchor_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(50) NOT NULL,
    display_name character varying(150) NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    trigger_status character varying(50) NOT NULL,
    json_fields_expression character varying(500) NOT NULL,
    batch_size_threshold integer DEFAULT 10 NOT NULL,
    batch_timeout_minutes integer DEFAULT 5 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_source_system character varying(50),
    legacy_source_table character varying(80),
    legacy_id character varying(100),
    legacy_source_hash character varying(64),
    legacy_migrated_at timestamp with time zone,
    legacy_mapping_version character varying(30),
    legacy_batch_id uuid,
    CONSTRAINT anchor_policies_batch_size_threshold_check CHECK (((batch_size_threshold >= 1) AND (batch_size_threshold <= 500))),
    CONSTRAINT anchor_policies_batch_timeout_minutes_check CHECK (((batch_timeout_minutes >= 1) AND (batch_timeout_minutes <= 60)))
);


--
-- Name: anchor_records; Type: TABLE; Schema: blockchain; Owner: -
--

CREATE TABLE blockchain.anchor_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(50) NOT NULL,
    entity_id uuid NOT NULL,
    entity_code character varying(50) NOT NULL,
    schema_version character varying(20) DEFAULT 'v1.0'::character varying NOT NULL,
    commitment_hash character varying(66) NOT NULL,
    raw_data_hash character varying(66) NOT NULL,
    zk_vault_id uuid,
    ledger_block_number bigint,
    tx_index_in_block integer,
    merkle_path jsonb,
    status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    anchored_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    legacy_source_system character varying(50),
    legacy_source_table character varying(80),
    legacy_id character varying(100),
    legacy_source_hash character varying(64),
    legacy_migrated_at timestamp with time zone,
    legacy_mapping_version character varying(30),
    legacy_batch_id uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: bridge_sync_logs; Type: TABLE; Schema: blockchain; Owner: -
--

CREATE TABLE blockchain.bridge_sync_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ledger_block_number bigint NOT NULL,
    nda_chain_endpoint character varying(255) NOT NULL,
    rpc_method character varying(50) NOT NULL,
    request_tx_hash character varying(66),
    http_status_code integer,
    status character varying(30) NOT NULL,
    error_message text,
    retry_count integer DEFAULT 0 NOT NULL,
    triggered_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone
);


--
-- Name: ledger_blocks; Type: TABLE; Schema: blockchain; Owner: -
--

CREATE TABLE blockchain.ledger_blocks (
    block_number bigint NOT NULL,
    block_hash character varying(66) NOT NULL,
    previous_hash character varying(66) NOT NULL,
    merkle_root character varying(66) NOT NULL,
    tx_count integer NOT NULL,
    validator_address character varying(100) NOT NULL,
    block_signature text NOT NULL,
    status character varying(30) DEFAULT 'COMMITTED'::character varying NOT NULL,
    nda_chain_tx_hash character varying(66),
    nda_chain_block_number bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    CONSTRAINT ledger_blocks_tx_count_check CHECK ((tx_count >= 0))
);


--
-- Name: zk_proof_vault; Type: TABLE; Schema: blockchain; Owner: -
